import React from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  return (
    <nav className="bg-white shadow mb-6">
      <div className="container mx-auto px-4 py-3 flex justify-between items-center">
        <Link to="/" className="text-xl font-bold text-blue-700">
          Data Commons
        </Link>
        <div className="space-x-4">
          <Link to="/" className="text-gray-700 hover:text-blue-700">
            Home
          </Link>
          {user && (
            <>
              <Link
                to="/dashboard"
                className="text-gray-700 hover:text-blue-700"
              >
                Dashboard
              </Link>
              <Link to="/upload" className="text-gray-700 hover:text-blue-700">
                Upload
              </Link>
              <button
                onClick={handleLogout}
                className="text-gray-700 hover:text-red-600 ml-2"
              >
                Logout
              </button>
            </>
          )}
          {!user && (
            <Link to="/login" className="text-gray-700 hover:text-blue-700">
              Login
            </Link>
          )}
        </div>
      </div>
    </nav>
  );
}
